on conflict (id) do update set name = excluded.name, tagline = excluded.tagline, icon = excluded.icon, hue = excluded.hue, sort = excluded.sort;
on conflict (id) do update set domain_id = excluded.domain_id, title = excluded.title, context = excluded.context, qotw_week = excluded.qotw_week, time_capsule = excluded.time_capsule;
on conflict (key) do update set display = excluded.display, founder = excluded.founder;
on conflict (id) do nothing;
